css:
.qdTh svg{width:100%;height:auto;display:block}
.qdTh .wall{fill:#26332f}
.qdTh .floor{fill:#1e2724}
.qdTh .shelf{fill:#46544e}
.qdTh .banner{fill:#2a5c58}
.qdTh .cnt{fill:#5d4633}
.qdTh .top{fill:#8b7459}
.qdTh .reg{fill:#39434b}
.qdTh .glass{fill:#3d5666}
.qdTh .btxt{font-family:'Shippori Mincho','Hiragino Mincho ProN','Yu Mincho',serif;font-weight:800;font-size:13px;fill:#fff;letter-spacing:.12em}
.qdTh .emo{font:800 20px 'Shippori Mincho','Hiragino Mincho ProN','Yu Mincho',serif;opacity:0;transition:opacity .2s}
.qdTh .emo.on{opacity:1}
.qdTh .breathe{animation:breathe 3.2s ease-in-out infinite}
.qdTh .eyes{animation:blink 4.6s infinite;transform-box:fill-box;transform-origin:center}
.qdTh .tailw{animation:tail 2.6s ease-in-out infinite;transform-box:fill-box;transform-origin:0% 100%}
.qdTh .mo{opacity:0}
.qdTh .hop{animation:hop .6s ease-out}
.qdTh .bow{animation:bow 1.1s ease-in-out}
.qdTh .nod{animation:nod .7s ease-in-out}
.qdTh .item,.qdTh .cash,.qdTh .chg,.qdTh .steam{opacity:0;transition:opacity .35s,transform .45s}
.qdTh .item{transform:translateY(-14px)}
.qdTh .bk{transition:opacity .3s}
.qdTh .glow{opacity:0;transition:opacity .3s}
.qdTh .top{display:flex;align-items:center;gap:8px}
.qdTh .bnavy{fill:#35568c}
.qdTh .sign{fill:#2f3a44}
.qdTh .stxt{font:700 10px 'Shippori Mincho','Hiragino Mincho ProN','Yu Mincho',serif;fill:#e8e2d6}
.qdTh .led{font:800 15px 'Shippori Mincho','Hiragino Mincho ProN','Yu Mincho',serif;fill:#ffb347;opacity:0;transition:opacity .35s}
.qdTh .tkt{opacity:0;transform:translateX(34px);transition:opacity .35s,transform .5s}
.qdTh .pp{opacity:0;transform:translateY(-8px);transition:opacity .35s,transform .45s}
.qdTh .s-a .pa{opacity:1;transform:none}
.qdTh .sm{opacity:0}
.qdTh .top{display:flex;gap:8px;flex-wrap:wrap}
.qdTh svg{width:100%;height:auto;display:block}
.qdTh .pp{opacity:0;transform:none}
.qdTh .pa{opacity:1}
